    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is autonomous trucking data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of long-range sensor data, scenario-targeted highway drives, and yard and dock recordings used to train and validate self-driving trucks, yard tractors, and the automation around freight hubs."
        }
      },
      {
        "@type": "Question",
        "name": "How is trucking data different from passenger-car data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Heavy trucks need longer stopping distances, so perception must be labeled at longer ranges. Trailers add articulation, and freight trips include yards and docks that passenger-car datasets rarely cover."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data in active work zones?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, through scenario-targeted drives that follow work zones as they appear and change, tagged by layout, time, and weather."
        }
      },
      {
        "@type": "Question",
        "name": "Do you collect yard and dock data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We record yard truck operations, trailer hookups, and dock approaches across shifts and weather, with pedestrian scenarios staged under the site's safety plan."
        }
      },
      {
        "@type": "Question",
        "name": "Can you help with trailer unloading robots?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We capture 3D scans of real trailer loads and teleoperated unloading demonstrations, including collapsed and floor-loaded freight."
        }
      },
      {
        "@type": "Question",
        "name": "Who has launched driverless trucking commercially?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Aurora began regular driverless customer deliveries between Dallas and Houston in May 2025, after more than three million autonomous miles in supervised pilots."
        }
      }
    ]
  }
